package com.himeros.messaging;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="messages")class Message{@Id private UUID id;@Column(name="conversation_id",nullable=false)private UUID conversationId;@Column(name="sender_id",nullable=false)private UUID senderId;@Column(nullable=false,length=4000)private String content;@Column(name="sent_at",nullable=false)private Instant sentAt;@Column(name="read_at")private Instant readAt;protected Message(){}Message(UUID conversationId,UUID sender,String content){id=UUID.randomUUID();this.conversationId=conversationId;senderId=sender;this.content=content;sentAt=Instant.now();}UUID id(){return id;}UUID conversation(){return conversationId;}UUID sender(){return senderId;}String content(){return content;}Instant sent(){return sentAt;}Instant read(){return readAt;}void markRead(){if(readAt==null)readAt=Instant.now();}}
